<script lang="ts">export let value='';export let inputId='mail-password';let visible=false;function generate(){const b=new Uint8Array(18);crypto.getRandomValues(b);value='Demo-'+Array.from(b,x=>x.toString(16).padStart(2,'0')).join('')+'!';visible=true;}</script>
<div class="field"><label for={inputId}>Password</label><div class="mail-pass"><input class="input" id={inputId} type={visible?'text':'password'} value={value} on:input={(e)=>value=e.currentTarget.value} minlength="8" maxlength="128" required autocomplete="new-password" placeholder="Enter a sample password"/><button class="btn secondary small" type="button" aria-label={visible?'Hide password':'Show password'} on:click={()=>visible=!visible}>{visible?'Hide':'Show'}</button><button class="btn secondary" type="button" on:click={generate}>Generate</button></div><small>At least 8 characters. Use sample credentials only.</small></div>
